import json, threading, sys, os
from pathlib import Path
from http.server import ThreadingHTTPServer, SimpleHTTPRequestHandler
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1]
os.chdir(ROOT)
class Quiet(SimpleHTTPRequestHandler):
 def log_message(self,*args): pass
server=ThreadingHTTPServer(('127.0.0.1',0),Quiet)
threading.Thread(target=server.serve_forever,daemon=True).start()
url=f'http://127.0.0.1:{server.server_port}/index.html'
checks=[]; errors=[]
def check(name,condition,detail=''):
 checks.append({'name':name,'pass':bool(condition),'detail':detail if not condition else ''})
 if not condition: print(f'FAIL {name}: {detail}')
PAD="""window.__pads=[null,null];navigator.getGamepads=()=>window.__pads;window.makePad=(i)=>({id:'DualSense emulated',index:i,connected:true,mapping:'standard',axes:[0,0,0,0],buttons:Array.from({length:17},()=>({pressed:false,touched:false,value:0})),timestamp:0});"""
with sync_playwright() as p:
 browser=p.chromium.launch(headless=True,args=['--enable-unsafe-webgpu','--enable-features=Vulkan','--use-webgpu-adapter=swiftshader','--disable-dev-shm-usage'])
 context=browser.new_context(viewport={'width':1280,'height':720})
 context.add_init_script(PAD)
 page=context.new_page();page.on('pageerror',lambda e:errors.append(str(e)))
 try:
  page.goto(url);page.wait_for_function('window.__game?.ready',timeout=60000)
  check('game identity',page.title()=='Chopper Palooza')
  check('WebGPU backend',page.evaluate('__game.backend')=='WebGPU')
  check('Rapier version',page.evaluate('__game.physicsVersion')=='0.19.3')
  check('native animation clips',page.evaluate('__game.diagnostics.animations')>=3)
  page.get_by_role('button',name='SETTINGS',exact=True).first.click()
  check('music default',page.locator('#music').input_value()=='10')
  page.locator('#music').fill('18');check('music live setting',page.evaluate('__game.audio.diagnostics().musicVolume')==.18)
  page.locator('#music').fill('10');page.locator('#settingsScreen [data-action=back]').click()
  page.evaluate('__game.start()')
  s=page.evaluate('__game.state');check('fresh patrol',len(s['trucks'])==6 and len(s['ships'])==1 and len(s['pilots'])==2)
  page.keyboard.down('d');page.evaluate('__game.step(1)');page.keyboard.up('d');s=page.evaluate('__game.state');check('keyboard flight',s['ships'][0]['x']>10)
  page.keyboard.down('w');page.evaluate('__game.step(4)');page.keyboard.up('w');check('ceiling clamp',page.evaluate('__game.state.ships[0].y')<=33)
  page.keyboard.down('Space');page.evaluate('__game.step(.5)');page.keyboard.up('Space');check('manual weapon',page.evaluate('__game.diagnostics.shotsFired')>=3)
  page.evaluate('__game.start();__game.setShip(0,14);__game.spawn("heli",8,14);__game.flare()');s=page.evaluate('__game.state');check('flare hits hostiles',s['kills']==1 and s['ships'][0]['flares']==2 and s['score']>=150)
  page.evaluate('__game.start();__game.setShip(22,4);__game.step(1.2)');s=page.evaluate('__game.state');check('hover rescue',s['rescues']>=1 and s['ships'][0]['flares']==4 and s['score']>=600)
  page.evaluate('__game.start();__game.setShip(0,14);__game.damageShip(120)');s=page.evaluate('__game.state');check('reserve respawn',s['ships'][0]['lives']==1 and s['ships'][0]['hp']==100)
  page.evaluate('__game.setShip(0,14);__game.damageShip(120);__game.setShip(0,14);__game.damageShip(120)');check('ship loss debrief',page.evaluate('__game.mode')=='debrief' and not page.evaluate('__game.state.won'))
  page.evaluate('__game.start();for(let i=0;i<6;i++)__game.damageTruck(i,1000)');check('convoy loss debrief',page.evaluate('__game.mode')=='debrief')
  page.evaluate('__game.start();__game.pause()');page.locator('#pauseScreen [data-action=dev]').click()
  page.locator('#dev-speed').fill('25');check('live balance slider',page.evaluate('__game.tuneValues.speed')==25)
  page.locator('#devScreen [data-action=resetTune]').click();check('balance reset',page.evaluate('__game.tuneValues.speed')==17)
  page.locator('#devScreen [data-action=back]').click();page.locator('#pauseScreen [data-action=resume]').click()
  page.evaluate('__pads[0]=makePad(0);__pads[0].axes[0]=1;__game.step(1)');check('gamepad flight',page.evaluate('__game.state.ships[0].x')>10)
  page.evaluate('__pads[0].axes[0]=0;__pads[0].buttons[9].pressed=true');page.wait_for_function('__game.screen()==="pause"');page.evaluate('__pads[0].buttons[9].pressed=false');page.wait_for_timeout(220);check('gamepad pause',page.evaluate('__game.screen()')=='pause')
  page.evaluate('__pads[0].buttons[13].pressed=true');page.wait_for_function('document.activeElement.dataset.action==="settings"');page.evaluate('__pads[0].buttons[13].pressed=false');page.wait_for_timeout(220);page.evaluate('__pads[0].buttons[0].pressed=true');page.wait_for_function('__game.screen()==="settings"');page.evaluate('__pads[0].buttons[0].pressed=false');check('gamepad menu navigation',page.evaluate('__game.screen()')=='settings')
  page.locator('#glyphs').select_option('xbox');page.evaluate('__pads[0].axes[0]=.3');page.wait_for_timeout(60);page.evaluate('__pads[0].axes[0]=0');check('Xbox prompts', 'RT FIRE' in page.locator('#controls').inner_text())
  page.locator('#glyphs').select_option('ps');page.evaluate('__game.menu("none");__pads[1]=makePad(1);__pads[1].buttons[0].pressed=true');page.wait_for_timeout(90);page.evaluate('__pads[1].buttons[0].pressed=false');check('second pad join',len(page.evaluate('__game.state.ships'))==2)
  page.evaluate('__pads=[null,null];__game.start();__game.upgrade("gun");__game.upgrade("armor")');s=page.evaluate('__game.state');check('field upgrades',s['stage']==2 and s['ships'][0]['maxHp']==125 and page.evaluate('__game.tuneValues.upgradePower')>1)
  page.evaluate('__game.start()');check('run upgrades reset',page.evaluate('__game.tuneValues.upgradePower')==1 and page.evaluate('__game.tuneValues.upgradeSpeed')==1)
  # The same input pilot used by attract mode flies and fights the entire campaign through Rapier.
  page.evaluate('__game.start();__game.invincible(true);__game.pilot(true)')
  campaign=page.evaluate('__game.step(260)')
  Path('tests/playthrough.json').write_text(json.dumps(campaign,indent=2))
  check('whole campaign victory',campaign['won'] and campaign['finished'],json.dumps({k:campaign[k] for k in ['stage','totalTime','kills','rescues','finished','won']}))
  check('all sectors and carrier',campaign['stage']==3 and campaign['bossSeen'] and campaign['upgrades']==3)
  check('campaign real collisions',campaign['kills']>=12 and campaign['score']>=10000 and page.evaluate('__game.diagnostics.shotsFired')>100)
  check('campaign rescue feature',campaign['rescues']>=1)
  check('network packet size',len(json.dumps(campaign).encode())<15500)
  page.evaluate('__game.start();__game.invincible(false);__game.pilot(true)')
  balanced=page.evaluate('__game.step(260)');Path('tests/balance-playthrough.json').write_text(json.dumps(balanced,indent=2))
  check('campaign survives without cheats',balanced['won'],json.dumps({k:balanced[k] for k in ['totalTime','kills','rescues','won','mode']}))
  page.evaluate('__game.pilot(false);__game.invincible(false)')
  audio=page.evaluate('__game.offlineAudio()');check('offline procedural audio',audio['finite'] and .001<audio['rms']<.5 and audio['peak']<=1,str(audio))
  page.evaluate('__game.title()');page.wait_for_function('__game.mode==="attract"',timeout=15000);check('10 second attract entry',page.evaluate('__game.mode')=='attract')
  page.evaluate('__game.step(230)');check('attract loop remains healthy',page.evaluate('__game.mode')=='attract' and page.evaluate('__game.state.totalTime')<210)
  page.keyboard.press('ArrowRight');check('attract input exits',page.evaluate('__game.mode')=='title')
  page.evaluate('__game.realtime()')
  # Standalone main-game integration, as opposed to adapter-only traffic checks.
  page.locator('[data-action=online]').first.click();page.locator('[data-action=host]').click();page.wait_for_function('document.getElementById("roomDisplay").textContent.length===6');code=page.locator('#roomDisplay').inner_text()
  guest=context.new_page();guest.on('pageerror',lambda e:errors.append(str(e)));guest.goto(url);guest.wait_for_function('window.__game?.ready',timeout=60000);guest.locator('[data-action=online]').first.click();guest.locator('#roomCode').press_sequentially('PPPPPP');check('room code keyboard input',guest.evaluate('__game.screen()')=='online' and guest.locator('#roomCode').input_value()=='PPPPPP');guest.locator('#roomCode').fill(code);guest.locator('[data-action=join]').click();page.wait_for_function('__game.online.connected',timeout=15000);guest.wait_for_function('__game.online.connected',timeout=15000);guest.wait_for_timeout(350)
  check('standalone two-player patrol',len(page.evaluate('__game.state.ships'))==2 and len(guest.evaluate('__game.state.ships'))==2)
  x=page.evaluate('__game.state.ships[1].x');guest.keyboard.down('d');guest.wait_for_timeout(750);guest.keyboard.up('d');moved=page.evaluate('__game.state.ships[1].x');check('guest input reaches authority',moved>x+3,f'{x}->{moved}')
  page.locator('#pauseButton').click();guest.wait_for_timeout(250);check('guest sees host pause',guest.locator('#attract').is_visible())
  page.locator('#pauseScreen [data-action=dev]').click();page.locator('#devScreen [data-action=victory]').click();guest.wait_for_function('__game.state.finished');guest.wait_for_timeout(150);check('co-op final score sync',page.evaluate('__game.state.score')==guest.evaluate('__game.state.score') and page.locator('#debriefStats .stat b').first.inner_text()==guest.locator('#debriefStats .stat b').first.inner_text());page.locator('#debriefScreen [data-action=title]').click();guest.wait_for_timeout(400);check('guest disconnect safe',guest.evaluate('__game.mode')=='disconnected' and guest.evaluate('__game.screen()')=='online');guest.close()
  check('no browser runtime errors',not errors,'; '.join(errors))
  # Test final standalone file directly, with no server required.
  page.goto((ROOT.parent/(ROOT.name+'.html')).as_uri());page.wait_for_function('window.__game?.ready',timeout=60000);check('single file boot',page.title()=='Chopper Palooza' and page.evaluate('__game.ready'))
  context.close()
  touch=browser.new_context(viewport={'width':844,'height':390},has_touch=True,is_mobile=True,device_scale_factor=1)
  mobile=touch.new_page();mobile.on('pageerror',lambda e:errors.append(str(e)));mobile.goto(url);mobile.wait_for_function('window.__game?.ready',timeout=60000);mobile.locator('[data-action=start]').tap();mobile.evaluate('__game.invincible(true)')
  cdp=touch.new_cdp_session(mobile);cdp.send('Input.dispatchTouchEvent',{'type':'touchStart','touchPoints':[{'x':110,'y':250,'id':7}]});cdp.send('Input.dispatchTouchEvent',{'type':'touchMove','touchPoints':[{'x':170,'y':210,'id':7}]});cdp.send('Input.dispatchTouchEvent',{'type':'touchStart','touchPoints':[{'x':170,'y':210,'id':7},{'x':730,'y':150,'id':8}]});mobile.wait_for_timeout(300)
  check('touch flight and assistance',mobile.evaluate('__game.state.ships[0].x')>1 and mobile.evaluate('__game.diagnostics.shotsFired')>0)
  check('touch minimal HUD',mobile.locator('#radarFrame').is_hidden())
  cdp.send('Input.dispatchTouchEvent',{'type':'touchEnd','touchPoints':[]});check('touch has no runtime errors',not errors,'; '.join(errors));touch.close()
 except Exception as e: check('test execution',False,str(e))
 finally: browser.close();server.shutdown()
Path('tests/core-results.json').write_text(json.dumps(checks,indent=2))
failed=sum(not c['pass'] for c in checks)
print(f'{len(checks)-failed}/{len(checks)} core checks passed')
sys.exit(bool(failed))
